{"code": "import subprocess
result = subprocess.run(["ps", "aux"], capture_output=True, text=True)
lines = result.stdout.strip().split("\n")[1:]
hermes_procs = []
for line in lines:
    cols = line.split()
    cmd = " ".join(cols[10:])
    if "hermes" in cmd and all(kw not in cmd for kw in ["grep","dashboard","orchestrator","uvicorn","sandbox","entrypoint","tini","senator","gateway"]):
        hermes_procs.append((float(cols[2]), cols[1], cols[8], " ".join(cols[10:])[:80]))

hermes_procs.sort(reverse=True)
for cpu, pid, start, cmd in hermes_procs:
    print(f"{pid:>8}  {cpu:5.1f}%  started={start}  {cmd}")
